#!/bin/bash
VERBEUX=0
PORT=/dev/ttyUSB0
while getopts "vp:h" opt; do
  case $opt in
    v) VERBEUX=1 ;;
    p) PORT=$OPTARG ;;
    h) echo "Usage : $0 [-v] [-p port]"; exit 0 ;;
    *) exit 1 ;;
  esac
done
shift $((OPTIND - 1))      # $1 désigne maintenant le premier argument restant
[ "$VERBEUX" -eq 1 ] && echo "port : $PORT"

