#include <stdio.h>

int main(void)
{
    int etat = 2;

    switch (etat) {
    case 0:  printf("arrêt\n");    break;
    case 1:  printf("veille\n");   break;
    case 2:  printf("actif\n");    break;
    default: printf("inconnu\n");  break;
    }

    int essais = 0;
    do {
        essais++;
        printf("tentative %d\n", essais);
    } while (essais < 3);

    for (int i = 0; i < 10; i++) {
        if (i % 2 == 0)
            continue;            /* passe aux nombres impairs */
        printf("%d ", i);
    }
    printf("\n");
    return 0;
}

